// 한 줄 버전 — 콘솔에 그대로 붙여넣기
((d)=>{const i={url:location.href,title:document.title,domain:location.hostname,ts:new Date().toISOString()};const ins=Array.from(d.querySelectorAll('input')).map(e=>({type:e.type,name:e.name,id:e.id,class:e.className,autocomplete:e.autocomplete,placeholder:e.placeholder,value:e.value,hidden:e.hidden||e.type==='hidden'}));const fs=Array.from(d.forms).map(f=>({id:f.id,name:f.name,action:f.action,method:f.method}));const h=d.documentElement.outerHTML;const s={info:i,forms:fs,inputCount:ins.length,visibleInputs:ins.filter(x=>!x.hidden),autofillCandidates:ins.filter(x=>x.autocomplete&&['username','email','current-password','new-password','one-time-code'].some(k=>x.autocomplete.includes(k))),allInputs:ins};console.group('🔍 KIYO Dump');console.log('📋',s);console.log('📄 HTML('+h.length+'):',h);console.groupEnd();navigator.clipboard?.writeText(h).then(()=>console.log('✅ outerHTML copied'))})(document);
